// OpenRGB (gitlab.com/CalcProgrammer1/OpenRGB) controls the RGB lighting of keyboards, mice,
// headsets, GPUs, RAM, coolers and motherboards over reverse-engineered USB HID and SMBus/I2C
// protocols. Its "Supported Devices" wiki tables are generated by scripts/build-supported-devices-md.sh
// from preprocessed sources, and the published CI artifact currently has empty names and ids, so
// this importer reads the same thing from the sources: every REGISTER_*_DETECTOR("Name", Detect…,
// VID, PID, …) in Controllers/** (VID/PID #defines resolved per controller), with the device
// category taken from the @category/@detectors doc comments of the RGBController_*.cpp files.
// Files come from the official read-only GitHub mirror (github.com/CalcProgrammer1/OpenRGB),
// because gitlab.com rate-limits unauthenticated raw downloads to a few dozen per IP.
// Skipped: detectors with no fixed device (network lights, E1.31, generic SMBus families, QMK
// and Logitech HID++ dynamic detectors). Sources are GPL-2.0-or-later (a few files GPL-2.0-only).
import { makeId, today, type DeviceRecord, type InstallRoute } from "@opendevicedb/core";
import { clean, githubFiles, githubRaw, mapLimit, type Source } from "../lib.ts";

const MIRROR = "CalcProgrammer1/OpenRGB", BRANCH = "master";
const GITLAB = "https://gitlab.com/CalcProgrammer1/OpenRGB/-/tree/master";

// ---------- C source scanning ----------

/** Remove // and /* *\/ comments, keeping string literals intact. */
export const stripComments = (src: string) =>
  src.replace(/"(?:\\.|[^"\\\n])*"|\/\/[^\n]*|\/\*[\s\S]*?\*\//g, (m) => (m.startsWith('"') ? m : m.startsWith("//") ? "" : m.replace(/[^\n]/g, " ")));

/** `#define NAME value` lines (object-like macros only). */
export function parseDefines(src: string, into = new Map<string, string>()): Map<string, string> {
  for (const m of stripComments(src).matchAll(/^[ \t]*#[ \t]*define[ \t]+([A-Za-z_]\w*)[ \t]+([^\n\\]+)$/gm)) {
    if (!into.has(m[1])) into.set(m[1], m[2].trim());
  }
  return into;
}

/** Split a macro argument list on top-level commas. */
export function splitArgs(s: string): string[] {
  const out: string[] = [];
  let depth = 0, cur = "", str = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (str) { cur += c; if (c === "\\") cur += s[++i] ?? ""; else if (c === '"') str = false; continue; }
    if (c === '"') { str = true; cur += c; continue; }
    if (c === "(") depth++;
    if (c === ")") depth--;
    if (c === "," && depth === 0) { out.push(cur.trim()); cur = ""; continue; }
    cur += c;
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}

export interface Detector { macro: string; args: string[] }

/** Every REGISTER_…(…) call in a source file (not the #define of the macros themselves). */
export function parseDetectors(src: string): Detector[] {
  const text = stripComments(src);
  const out: Detector[] = [];
  for (const m of text.matchAll(/\b(REGISTER_[A-Z0-9_]+)\s*\(/g)) {
    const lineStart = text.lastIndexOf("\n", m.index) + 1;
    if (/^\s*#\s*define/.test(text.slice(lineStart, m.index))) continue;
    let depth = 1, i = m.index! + m[0].length, str = false;
    for (; i < text.length && depth; i++) {
      const c = text[i];
      if (str) { if (c === "\\") i++; else if (c === '"') str = false; continue; }
      if (c === '"') str = true; else if (c === "(") depth++; else if (c === ")") depth--;
    }
    out.push({ macro: m[1], args: splitArgs(text.slice(m.index! + m[0].length, i - 1)) });
  }
  return out;
}

type Lookup = (name: string) => string | undefined;

/** String literal(s), possibly through #defines: "Razer " "Naga" → "Razer Naga". */
export function resolveString(expr: string, lookup: Lookup, depth = 0): string | null {
  const e = expr.trim();
  if (depth > 8 || !e) return null;
  if (/^("(?:\\.|[^"\\])*"\s*)+$/.test(e)) return [...e.matchAll(/"((?:\\.|[^"\\])*)"/g)].map((m) => m[1].replace(/\\(.)/g, "$1")).join("");
  if (/^[A-Za-z_]\w*$/.test(e)) { const v = lookup(e); return v == null ? null : resolveString(v, lookup, depth + 1); }
  if (/^\(.*\)$/.test(e)) return resolveString(e.slice(1, -1), lookup, depth + 1);
  return null;
}

/** Integer literal, possibly through #defines and casts / parentheses. */
export function resolveNumber(expr: string, lookup: Lookup, depth = 0): number | null {
  let e = expr.trim().replace(/^\((?:uint16_t|unsigned short|unsigned int|int)\)\s*/, "");
  if (depth > 8 || !e) return null;
  if (/^0x[0-9a-f]+u?l?$/i.test(e)) return parseInt(e, 16);
  if (/^\d+u?l?$/i.test(e)) return parseInt(e, 10);
  if (/^[A-Za-z_]\w*$/.test(e)) { const v = lookup(e); return v == null ? null : resolveNumber(v, lookup, depth + 1); }
  if (/^\(.*\)$/.test(e)) return resolveNumber(e.slice(1, -1), lookup, depth + 1);
  return null;
}

/** @category and @detectors of RGBController doc comments → detector function → categories. */
export function parseDocCategories(src: string, into = new Map<string, string[]>()): Map<string, string[]> {
  for (const block of src.split("/**").slice(1)) {
    const body = block.split(/\\\*\/|\*\//)[0];
    const cats = body.match(/@category\s+([^\n|]*)/)?.[1];
    const dets = body.match(/@detectors\s+([^\n]*)/)?.[1];
    if (!cats || !dets) continue;
    const list = cats.split(/[,/]/).map((c) => c.trim().toLowerCase()).filter(Boolean);
    for (const d of dets.split(",").map((x) => x.trim()).filter(Boolean)) into.set(d, [...(into.get(d) ?? []), ...list]);
  }
  return into;
}

/** `vendor = "Razer";` in RGBController constructors: the brand spellings OpenRGB itself uses. */
export const parseVendors = (src: string) => [...src.matchAll(/\bvendor\s*=\s*"([^"]+)"/g)].map((m) => clean(m[1])).filter((v) => v && !/^unknown$/i.test(v));

// ---------- records ----------

/** Brands of more than one word that a first-word split would cut. */
export const MULTIWORD_VENDORS = ["Cooler Master", "Lian Li", "Das Keyboard", "Dark Project", "Red Square", "Turtle Beach", "Team Group", "Western Digital", "Dream Cheeky", "Glorious PC Gaming Race", "MNT Research", "Black Shark", "Raspberry Pi", "Attack Shark"];

/** Connection / layout / id variants of one product, merged into one record. */
const VARIANT = /\s*\((?:[^)]*\b(?:wired|wireless|receiver|dongle|bluetooth|bt|usb|lightspeed|2\.4\s?ghz|pid|ansi|iso|jis|abnt|layout|charging|dock)\b[^)]*)\)/gi;

/** "Razer Naga Pro V2 (Wired)" → Razer / Naga Pro V2, using known brand spellings. */
export function splitDeviceName(name: string, vendors: string[]): { vendor: string; model: string } {
  const n = clean(name);
  const lower = n.toLowerCase();
  const hit = vendors
    .filter((v) => lower.startsWith(v.toLowerCase()) && (n.length === v.length || n[v.length] === " "))
    .sort((a, b) => b.length - a.length)[0];
  const vendor = hit ? n.slice(0, hit.length) : n.split(" ")[0];
  const model = clean(n.slice(vendor.length).replace(VARIANT, ""));
  return model ? { vendor, model } : { vendor, model: clean(n.replace(VARIANT, "")) || n };
}

/** OpenRGB categories → ours: the controlled part is a PC peripheral, except lights and laptops. */
export function openrgbCategory(cats: string[] | undefined): string {
  const c = cats ?? [];
  if (c.length && c.every((x) => x === "light")) return "light";
  if (c.length && c.every((x) => x === "laptop")) return "laptop";
  return "peripheral";
}

const hex4 = (n: number) => n.toString(16).padStart(4, "0");

/** Class drivers that match any device of a kind, not one product. */
const GENERIC_NAME = /^(HID LampArray|Generic\b)/i;

export interface Entry { name: string; func: string; dir: string; usb?: string; bus: "usb" | "smbus" }

/** One REGISTER_… call → entry, or null for detectors without a fixed device. */
export function toEntry(d: Detector, dir: string, lookup: Lookup): Entry | null {
  const m = d.macro;
  let nameArg: string, func: string, vid: string | undefined, pid: string | undefined, bus: Entry["bus"];
  if (/^REGISTER_HID(_WRAPPED)?_DETECTOR/.test(m)) [nameArg, func, vid, pid, bus] = [d.args[0], d.args[1], d.args[2], d.args[3], "usb"];
  else if (m === "REGISTER_WOOTING_DETECTOR") [nameArg, func, vid, pid, bus] = [d.args[0], "DetectWootingControllers", d.args[1], d.args[2], "usb"];
  else if (/^REGISTER_I2C_(PCI|DRAM)_DETECTOR/.test(m)) [nameArg, func, bus] = [d.args[0], d.args[1], "smbus"];
  else return null; // REGISTER_DETECTOR, REGISTER_I2C_DETECTOR, dynamic and udev registrations
  const name = resolveString(nameArg ?? "", lookup);
  if (!name || !clean(name) || GENERIC_NAME.test(clean(name))) return null;
  const e: Entry = { name: clean(name), func: clean(func), dir, bus };
  if (bus === "usb") {
    const v = resolveNumber(vid ?? "", lookup), p = resolveNumber(pid ?? "", lookup);
    if (v == null || p == null || v > 0xffff || p > 0xffff) return null; // HID_PID_ANY and friends
    e.usb = `${hex4(v)}:${hex4(p)}`;
  }
  return e;
}

/**
 * Install route (SPEC R1): OpenRGB runs on the computer the device is attached to; nothing is
 * flashed. Guides are the official access setup pages (USB permissions, or SMBus drivers for
 * RAM, GPUs and motherboards). OpenRGB's README warns that some hardware has been damaged by
 * its reverse-engineered protocols in the past: risk "low", not "none".
 */
export function openrgbInstall(bus: Entry["bus"]): InstallRoute {
  const smbus = bus === "smbus";
  return {
    project: "OpenRGB",
    method: "host-software",
    guide: `${GITLAB.replace("/-/tree/", "/-/blob/")}/Documentation/${smbus ? "SMBusAccess" : "USBAccess"}.md`,
    installer: "https://openrgb.org/releases.html",
    difficulty: smbus ? "medium" : "easy",
    brick_risk: "low",
    reversible: "yes",
    notes: smbus
      ? "Nothing is flashed. SMBus/I2C access must be enabled first (a driver on Windows, kernel modules on Linux). OpenRGB warns that its reverse-engineered protocols have damaged some hardware in the past."
      : "Nothing is flashed: OpenRGB sets the lighting over USB from your computer. OpenRGB warns that its reverse-engineered protocols have damaged some hardware in the past.",
  };
}

export function fromEntry(e: Entry, vendors: string[], categories: Map<string, string[]>, date = today()): DeviceRecord {
  const { vendor, model } = splitDeviceName(e.name, vendors);
  return {
    id: makeId(vendor, model),
    vendor,
    model,
    aliases: [clean(e.name.replace(/\s*\(PID 0x[0-9a-f]+\)/gi, ""))],
    category: openrgbCategory(categories.get(e.func)),
    identifiers: { usb: e.usb ? [e.usb] : [] },
    status: "controllable",
    interfaces: [{
      name: "RGB lighting",
      transport: e.bus === "usb" ? "usb" : "other",
      status: "documented",
      notes: e.bus === "usb" ? "Lighting control only, USB HID (OpenRGB)" : "Lighting control only, SMBus/I2C (OpenRGB)",
    }],
    projects: [{ name: "OpenRGB", url: `${GITLAB}/${e.dir.split("/").map(encodeURIComponent).join("/")}`, kind: "driver", license: "GPL-2.0-or-later" }],
    install: [openrgbInstall(e.bus)],
    provenance: { sources: ["openrgb"] },
    updated: date,
  };
}

/** All Controllers/** files (path → text) → records. #defines resolve within the top controller directory first. */
export function fromSources(files: Map<string, string>, date = today()): { records: DeviceRecord[]; detectors: number; skipped: number } {
  const top = (p: string) => p.split("/").slice(0, 2).join("/");
  const local = new Map<string, Map<string, string>>(), global = new Map<string, string>();
  const categories = new Map<string, string[]>();
  const vendors = new Set(MULTIWORD_VENDORS);
  for (const [p, src] of files) {
    const t = top(p);
    if (!local.has(t)) local.set(t, new Map());
    parseDefines(src, local.get(t));
    parseDefines(src, global);
    if (/RGBController_[^/]*\.(cpp|h)$/.test(p)) { parseDocCategories(src, categories); parseVendors(src).forEach((v) => vendors.add(v)); }
  }
  const vendorList = [...vendors];
  const records: DeviceRecord[] = [];
  let detectors = 0, skipped = 0;
  for (const [p, src] of files) {
    if (!p.endsWith(".cpp")) continue;
    const defs = local.get(top(p))!;
    const lookup: Lookup = (n) => defs.get(n) ?? global.get(n);
    const dir = p.split("/").slice(0, -1).join("/");
    for (const d of parseDetectors(src)) {
      detectors++;
      const e = toEntry(d, dir, lookup);
      if (e) records.push(fromEntry(e, vendorList, categories, date));
      else skipped++;
    }
  }
  return { records, detectors, skipped };
}

const source: Source = {
  source: "openrgb",
  name: "OpenRGB supported devices",
  url: "https://gitlab.com/CalcProgrammer1/OpenRGB",
  license: "GPL-2.0-or-later",
  async fetch() {
    const paths = (await githubFiles(MIRROR, BRANCH)).filter((p) => p.startsWith("Controllers/") && /\.(cpp|h)$/.test(p));
    const texts = await mapLimit(paths, 16, (p) => githubRaw(MIRROR, BRANCH, p));
    const { records, detectors, skipped } = fromSources(new Map(paths.map((p, i) => [p, texts[i]])));
    console.error(`openrgb: ${paths.length} source files, ${detectors} detector registrations, ${skipped} without a fixed device`);
    return records;
  },
};
export default source;
